import{_ as l,a0 as p,w as r,s as o,I as i,x as a,a1 as n,A as e,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"使用 Stratis 的網絡綁定磁盤加密 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Stratis 的網絡綁定磁盤加密 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Stratis 的網絡綁定磁盤加密 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Stratis 的網絡綁定磁盤加密 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210407 Using network bound disk encryption with Stratis","title":"使用 Stratis 的網絡綁定磁盤加密","tag":"202104","desc":""},"relativePath":"202104/20210407 Using network bound disk encryption with Stratis.md","filePath":"[post].md"}'),g={name:"202104/20210407 Using network bound disk encryption with Stratis.md"};function h(k,s,b,u,c,f){const t=p("Link");return r(),o("div",null,[s[40]||(s[40]=i("h1",{id:"使用-stratis-的網絡綁定磁盤加密",tabindex:"-1"},[a("使用 Stratis 的網絡綁定磁盤加密 "),i("a",{class:"header-anchor",href:"#使用-stratis-的網絡綁定磁盤加密","aria-label":"Permalink to “使用 Stratis 的網絡綁定磁盤加密”"},"​")],-1)),s[41]||(s[41]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/27/221704gyzyvyroyyrybany.jpg",alt:""})],-1)),i("p",null,[s[1]||(s[1]=a("在一個有許多加密磁盤的環境中，解鎖所有的磁盤是一項困難的任務。",-1)),s[2]||(s[2]=i("ruby",null,[a("網絡綁定磁盤加密"),i("rt",null,"Network bound disk encryption")],-1)),s[3]||(s[3]=a("（NBDE）有助於自動解鎖 Stratis 卷的過程。這是在大型環境中的一個關鍵要求。Stratis 2.1 版本增加了對加密的支持，這在《",-1)),n(t,{href:"https://linux.cn/article-13311-1.html"},{default:e(()=>[...s[0]||(s[0]=[a("Stratis 加密入門",-1)])]),_:1}),s[4]||(s[4]=a("》一文中介紹過。Stratis 2.3 版本最近在使用加密的 Stratis 池時引入了對網絡綁定磁盤加密（NBDE）的支持，這是本文的主題。",-1))]),i("p",null,[n(t,{href:"https://stratis-storage.github.io/"},{default:e(()=>[...s[5]||(s[5]=[a("Stratis 網站",-1)])]),_:1}),s[7]||(s[7]=a(" 將 Stratis 描述為一個“",-1)),s[8]||(s[8]=i("em",null,"易於使用的 Linux 本地存儲管理",-1)),s[9]||(s[9]=a("”。短視頻《",-1)),n(t,{href:"https://www.youtube.com/watch?v=CJu3kmY-f5o"},{default:e(()=>[...s[6]||(s[6]=[a("使用 Stratis 管理存儲",-1)])]),_:1}),s[10]||(s[10]=a("》對基礎知識進行了快速演示。該視頻是在 Red Hat Enterprise Linux 8 系統上錄製的，然而，視頻中顯示的概念也適用於 Fedora Linux 中的 Stratis。",-1))]),s[42]||(s[42]=i("h3",{id:"先決條件",tabindex:"-1"},[a("先決條件 "),i("a",{class:"header-anchor",href:"#先決條件","aria-label":"Permalink to “先決條件”"},"​")],-1)),i("p",null,[s[13]||(s[13]=a("本文假設你熟悉 Stratis，也熟悉 Stratis 池加密。如果你不熟悉這些主題，請參考這篇 ",-1)),n(t,{href:"https://linux.cn/article-13311-1.html"},{default:e(()=>[...s[11]||(s[11]=[a("文章",-1)])]),_:1}),s[14]||(s[14]=a(" 和前面提到的 ",-1)),n(t,{href:"https://www.youtube.com/watch?v=CJu3kmY-f5o"},{default:e(()=>[...s[12]||(s[12]=[a("Stratis 概述視頻",-1)])]),_:1}),s[15]||(s[15]=a("。",-1))]),s[43]||(s[43]=i("p",null,"NBDE 需要 Stratis 2.3 或更高版本。本文中的例子使用的是 Fedora Linux 34 的預發佈版本。Fedora Linux 34 的最終版本將包含 Stratis 2.3。",-1)),s[44]||(s[44]=i("h3",{id:"網絡綁定磁盤加密-nbde-概述",tabindex:"-1"},[a("網絡綁定磁盤加密（NBDE）概述 "),i("a",{class:"header-anchor",href:"#網絡綁定磁盤加密-nbde-概述","aria-label":"Permalink to “網絡綁定磁盤加密（NBDE）概述”"},"​")],-1)),s[45]||(s[45]=i("p",null,"加密存儲的主要挑戰之一是有一個安全的方法在系統重啓後再次解鎖存儲。在大型環境中，手動輸入加密口令並不能很好地擴展。NBDE 解決了這一問題，允許以自動方式解鎖加密存儲。",-1)),s[46]||(s[46]=i("p",null,"在更高層次上，NBDE 需要環境中的 Tang 服務器。客户端系統（使用 Clevis Pin）只要能與 Tang 服務器建立網絡連接，就可以自動解密存儲。如果網絡沒有連接到 Tang 服務器，則必須手動解密存儲。",-1)),s[47]||(s[47]=i("p",null,"這背後的想法是，Tang 服務器只能在內部網絡上使用，因此，如果加密設備丟失或被盜，它將不再能夠訪問內部網絡連接到 Tang 服務器，因此不會被自動解密。",-1)),i("p",null,[s[18]||(s[18]=a("關於 Tang 和 Clevis 的更多信息，請參見手冊頁（",-1)),s[19]||(s[19]=i("code",null,"man tang",-1)),s[20]||(s[20]=a("、",-1)),s[21]||(s[21]=i("code",null,"man clevis",-1)),s[22]||(s[22]=a("）、",-1)),n(t,{href:"https://github.com/latchset/tang"},{default:e(()=>[...s[16]||(s[16]=[a("Tang 的 GitHub 頁面",-1)])]),_:1}),s[23]||(s[23]=a(" 和 ",-1)),n(t,{href:"https://github.com/latchset/clevis"},{default:e(()=>[...s[17]||(s[17]=[a("Clevis 的 GitHub 頁面",-1)])]),_:1}),s[24]||(s[24]=a("。",-1))]),s[48]||(s[48]=d(`<h3 id="設置-tang-服務器" tabindex="-1">設置 Tang 服務器 <a class="header-anchor" href="#設置-tang-服務器" aria-label="Permalink to “設置 Tang 服務器”">​</a></h3><p>本例使用另一個 Fedora Linux 系統作為 Tang 服務器，主機名為 <code>tang-server</code>。首先安裝 <code>tang</code> 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf install tang</span></span></code></pre></div><p>然後用 <code>systemctl</code> 啓用並啓動 <code>tangd.socket</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl enable tangd.socket --now</span></span></code></pre></div><p>Tang 使用的是 TCP 80 端口，所以你也需要在防火牆中打開該端口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --add-port=80/tcp --permanent</span></span>
<span class="line"><span>firewall-cmd --add-port=80/tcp</span></span></code></pre></div><p>最後，運行 <code>tang-show-keys</code> 來顯示輸出簽名密鑰指紋。你以後會需要這個。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tang-show-keys</span></span>
<span class="line"><span>l3fZGUCmnvKQF_OA6VZF9jf8z2s</span></span></code></pre></div><h3 id="創建加密的-stratis-池" tabindex="-1">創建加密的 Stratis 池 <a class="header-anchor" href="#創建加密的-stratis-池" aria-label="Permalink to “創建加密的 Stratis 池”">​</a></h3><p>上一篇關於 Stratis 加密的文章詳細介紹瞭如何設置加密的 Stratis 池，所以本文不會深入介紹。</p><p>第一步是捕獲一個將用於解密 Stratis 池的密鑰。即使使用 NBDE，也需要設置這個，因為在 NBDE 服務器無法到達的情況下，可以用它來手動解鎖池。使用以下命令捕獲 <code>pool1</code> 密鑰。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key set --capture-key pool1key</span></span>
<span class="line"><span>Enter key data followed by the return key:</span></span></code></pre></div><p>然後我將使用 <code>/dev/vdb</code> 設備創建一個加密的 Stratis 池（使用剛才創建的 <code>pool1key</code>），命名為 <code>pool1</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool create --key-desc pool1key pool1 /dev/vdb。</span></span></code></pre></div><p>接下來，在這個 Stratis 池中創建一個名為 <code>filesystem1</code> 的文件系統，創建一個掛載點，掛載文件系統，並在其中創建一個測試文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis filesystem create pool1 filesystem1</span></span>
<span class="line"><span># mkdir /filesystem1</span></span>
<span class="line"><span># mount /dev/stratis/pool1/filesystem1 /filesystem1</span></span>
<span class="line"><span># cd /filesystem1</span></span>
<span class="line"><span># echo &quot;this is a test file&quot; &gt; testfile</span></span></code></pre></div><h3 id="將-stratis-池綁定到-tang-服務器上" tabindex="-1">將 Stratis 池綁定到 Tang 服務器上 <a class="header-anchor" href="#將-stratis-池綁定到-tang-服務器上" aria-label="Permalink to “將 Stratis 池綁定到 Tang 服務器上”">​</a></h3><p>此時，我們已經創建了加密的 Stratis 池，並在池中創建了一個文件系統。下一步是將你的 Stratis 池綁定到剛剛設置的 Tang 服務器上。使用 <code>stratis pool bind nbde</code> 命令進行。</p><p>當你進行 Tang 綁定時，需要向該命令傳遞幾個參數：</p><ul><li>池名（在本例中，<code>pool1</code>）</li><li>鑰匙描述符名稱（本例中為 <code>pool1key</code>）</li><li>Tang 服務器名稱（在本例中，<code>http://tang-server</code>）</li></ul><p>記得之前在 Tang 服務器上，運行了 <code>tang-show-keys</code>，顯示 Tang 輸出的簽名密鑰指紋是 <code>l3fZGUCmnvKQF_OA6VZF9jf8z2s</code>。除了前面的參數外，還需要用參數 <code>-thumbprint l3fZGUCmnvKQF_OA6VZF9jf8z2s</code> 傳遞這個指紋，或者用 <code>-trust-url</code> 參數跳過對指紋的驗證。</p><p>使用 <code>-thumbprint</code> 參數更安全。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool bind nbde pool1 pool1key http://tang-server --thumbprint l3fZGUCmnvKQF_OA6VZF9jf8z2s</span></span></code></pre></div><h3 id="用-nbde-解鎖-stratis-池" tabindex="-1">用 NBDE 解鎖 Stratis 池 <a class="header-anchor" href="#用-nbde-解鎖-stratis-池" aria-label="Permalink to “用 NBDE 解鎖 Stratis 池”">​</a></h3><p>接下來重啓主機，並驗證你可以用 NBDE 解鎖 Stratis 池，而不需要使用密鑰口令。重啓主機後，該池不再可用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name Total Physical Properties</span></span></code></pre></div><p>要使用 NBDE 解鎖池，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool unlock clevis</span></span></code></pre></div><p>注意，你不需要使用密鑰口令。這個命令可以在系統啓動時自動運行。</p><p>此時，Stratis 池已經可以使用了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name Total Physical Properties</span></span>
<span class="line"><span>pool1 4.98 GiB / 583.65 MiB / 4.41 GiB ~Ca, Cr</span></span></code></pre></div><p>你可以掛載文件系統，訪問之前創建的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount /dev/stratis/pool1/filesystem1 /filesystem1/</span></span>
<span class="line"><span># cat /filesystem1/testfile</span></span>
<span class="line"><span>this is a test file</span></span></code></pre></div><h3 id="輪換-tang-服務器密鑰" tabindex="-1">輪換 Tang 服務器密鑰 <a class="header-anchor" href="#輪換-tang-服務器密鑰" aria-label="Permalink to “輪換 Tang 服務器密鑰”">​</a></h3><p>最好定期輪換 Tang 服務器密鑰，並更新 Stratis 客户服務器以使用新的 Tang 密鑰。</p><p>要生成新的 Tang 密鑰，首先登錄到 Tang 服務器，查看 <code>/var/db/tang</code> 目錄的當前狀態。然後，運行 <code>tang-show-keys</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -al /var/db/tang</span></span>
<span class="line"><span>total 8</span></span>
<span class="line"><span>drwx------. 1 tang tang 124 Mar 15 15:51 .</span></span>
<span class="line"><span>drwxr-xr-x. 1 root root 16 Mar 15 15:48 ..</span></span>
<span class="line"><span>-rw-r--r--. 1 tang tang 361 Mar 15 15:51 hbjJEDXy8G8wynMPqiq8F47nJwo.jwk</span></span>
<span class="line"><span>-rw-r--r--. 1 tang tang 367 Mar 15 15:51 l3fZGUCmnvKQF_OA6VZF9jf8z2s.jwk</span></span>
<span class="line"><span># tang-show-keys</span></span>
<span class="line"><span>l3fZGUCmnvKQF_OA6VZF9jf8z2s</span></span></code></pre></div><p>要生成新的密鑰，運行 <code>tangd-keygen</code> 並將其指向 <code>/var/db/tang</code> 目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /usr/libexec/tangd-keygen /var/db/tang</span></span></code></pre></div><p>如果你再看看 <code>/var/db/tang</code> 目錄，你會看到兩個新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -al /var/db/tang</span></span>
<span class="line"><span>total 16</span></span>
<span class="line"><span>drwx------. 1 tang tang 248 Mar 22 10:41 .</span></span>
<span class="line"><span>drwxr-xr-x. 1 root root 16 Mar 15 15:48 ..</span></span>
<span class="line"><span>-rw-r--r--. 1 tang tang 361 Mar 15 15:51 hbjJEDXy8G8wynMPqiq8F47nJwo.jwk</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 354 Mar 22 10:41 iyG5HcF01zaPjaGY6L_3WaslJ_E.jwk</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 349 Mar 22 10:41 jHxerkqARY1Ww_H_8YjQVZ5OHao.jwk</span></span>
<span class="line"><span>-rw-r--r--. 1 tang tang 367 Mar 15 15:51 l3fZGUCmnvKQF_OA6VZF9jf8z2s.jwk</span></span></code></pre></div><p>如果你運行 <code>tang-show-keys</code>，就會顯示出 Tang 所公佈的密鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tang-show-keys</span></span>
<span class="line"><span>l3fZGUCmnvKQF_OA6VZF9jf8z2s</span></span>
<span class="line"><span>iyG5HcF01zaPjaGY6L_3WaslJ_E</span></span></code></pre></div><p>你可以通過將兩個原始文件改名為以句號開頭的隱藏文件，來防止舊的密鑰（以 <code>l3fZ</code> 開頭）被公佈。通過這種方法，舊的密鑰將不再被公佈，但是它仍然可以被任何沒有更新為使用新密鑰的現有客户端使用。一旦所有的客户端都更新使用了新密鑰，這些舊密鑰文件就可以刪除了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /var/db/tang</span></span>
<span class="line"><span># mv hbjJEDXy8G8wynMPqiq8F47nJwo.jwk   .hbjJEDXy8G8wynMPqiq8F47nJwo.jwk</span></span>
<span class="line"><span># mv l3fZGUCmnvKQF_OA6VZF9jf8z2s.jwk   .l3fZGUCmnvKQF_OA6VZF9jf8z2s.jwk</span></span></code></pre></div><p>此時，如果再運行 <code>tang-show-keys</code>，Tang 只公佈新鑰匙：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tang-show-keys</span></span>
<span class="line"><span>iyG5HcF01zaPjaGY6L_3WaslJ_E</span></span></code></pre></div><p>下一步，切換到你的 Stratis 系統並更新它以使用新的 Tang 密鑰。當文件系統在線時， Stratis 支持這樣做。</p><p>首先，解除對池的綁定：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool unbind pool1</span></span></code></pre></div><p>接下來，用創建加密池時使用的原始口令設置密鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key set --capture-key pool1key</span></span>
<span class="line"><span>Enter key data followed by the return key:</span></span></code></pre></div><p>最後，用更新後的密鑰指紋將 Stratis 池綁定到 Tang 服務器上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool bind nbde pool1 pool1key http://tang-server --thumbprint iyG5HcF01zaPjaGY6L_3WaslJ_E</span></span></code></pre></div><p>Stratis 系統現在配置為使用更新的 Tang 密鑰。一旦使用舊的 Tang 密鑰的任何其他客户系統被更新，在 Tang 服務器上的 <code>/var/db/tang</code> 目錄中被重命名為隱藏文件的兩個原始密鑰文件就可以被備份和刪除了。</p><h3 id="如果-tang-服務器不可用怎麼辦" tabindex="-1">如果 Tang 服務器不可用怎麼辦？ <a class="header-anchor" href="#如果-tang-服務器不可用怎麼辦" aria-label="Permalink to “如果 Tang 服務器不可用怎麼辦？”">​</a></h3><p>接下來，關閉 Tang 服務器，模擬它不可用，然後重啓 Stratis 系統。</p><p>重啓後，Stratis 池又不可用了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name Total Physical Properties</span></span></code></pre></div><p>如果你試圖用 NBDE 解鎖，會因為 Tang 服務器不可用而失敗：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool unlock clevis</span></span>
<span class="line"><span>Execution failed:</span></span>
<span class="line"><span>An iterative command generated one or more errors: The operation &#39;unlock&#39; on a resource of type pool failed. The following errors occurred:</span></span>
<span class="line"><span>Partial action &quot;unlock&quot; failed for pool with UUID 4d62f840f2bb4ec9ab53a44b49da3f48: Cryptsetup error: Failed with error: Error: Command failed: cmd: &quot;clevis&quot; &quot;luks&quot; &quot;unlock&quot; &quot;-d&quot; &quot;/dev/vdb&quot; &quot;-n&quot; &quot;stratis-1-private-42142fedcb4c47cea2e2b873c08fcf63-crypt&quot;, exit reason: 1 stdout: stderr: /dev/vdb could not be opened.</span></span></code></pre></div><p>此時，在 Tang 服務器無法到達的情況下，解鎖池的唯一選擇就是使用原密鑰口令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key set --capture-key pool1key</span></span>
<span class="line"><span>Enter key data followed by the return key:</span></span></code></pre></div><p>然後你可以使用鑰匙解鎖池：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool unlock keyring</span></span></code></pre></div><p>接下來，驗證池是否成功解鎖：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name Total Physical Properties</span></span>
<span class="line"><span>pool1 4.98 GiB / 583.65 MiB / 4.41 GiB ~Ca, Cr</span></span></code></pre></div><hr>`,69)),i("p",null,[s[26]||(s[26]=a("via: ",-1)),n(t,{href:"https://fedoramagazine.org/network-bound-disk-encryption-with-stratis/"},{default:e(()=>[...s[25]||(s[25]=[a("https://fedoramagazine.org/network-bound-disk-encryption-with-stratis/",-1)])]),_:1})]),i("p",null,[s[31]||(s[31]=a("作者：",-1)),n(t,{href:"https://fedoramagazine.org/author/briansmith/"},{default:e(()=>[...s[27]||(s[27]=[a("briansmith",-1)])]),_:1}),s[32]||(s[32]=a(" 選題：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[28]||(s[28]=[a("lujun9972",-1)])]),_:1}),s[33]||(s[33]=a(" 譯者：",-1)),n(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[29]||(s[29]=[a("wxy",-1)])]),_:1}),s[34]||(s[34]=a(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[30]||(s[30]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[37]||(s[37]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[35]||(s[35]=[a("LCTT",-1)])]),_:1}),s[38]||(s[38]=a(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:e(()=>[...s[36]||(s[36]=[a("Linux中國",-1)])]),_:1}),s[39]||(s[39]=a(" 榮譽推出",-1))])])}const C=l(g,[["render",h]]);export{v as __pageData,C as default};
